REQUIRED = ['question', 'data', 'method', 'results', 'trial_count', 'dsr', 'what_failed', 'next_steps']

def results_table(gross, net, costs):
    lines = [f'gross: {gross:.2f}']
    for c, s in zip(costs, net):
        lines.append(f'net at {c} bp: {s:.2f}')
    return lines

def write_up_sections(results):
    return [k for k in REQUIRED if results.get(k) in (None, '', [], {})]
